const reviewedInThisSupplement=new Set(['rosentour','boberg-route','vier-marschlande-highlight','weinfass','hamburgboats','adfc-touren','segelflugplatz-boberg','gokart-hof','kutschfahrten-burmester','megaballs','allermoeher-wiesen','alter-holzhafen','spadenlaender-spitze','bergedorfer-gehoelz','karoline','wochenmaerkte-bergedorf','bergedorfer-stadtfest','bergedorfer-weihnachtsmarkt','wutzrock','hiamo','haus-anna-elbe','elberadweg','maler-lackierer-museum','reitbrooker-muehle','geschichtskontor','berg-museumslandschaft','kuenstlerhaus-bergedorf','white-cube-bergedorf','hansa-filmstudio','swingolf-hamburg','golf-lounge-moorfleet','minigolf-gruenes-zentrum','drachenlabyrinth','boberger-reitverein','erlebnisbauernhof-burmester-reiten','milchhof-reitbrook','ackerperlen','biohof-sommerfeld','vier-marschlande-querbeet','tatenberger-schleuse','schoepfwerke-vier-marschlande','kiebitzbrack','bodenlehrpfad-boberg','grosse-bergedorfer-runde','vierlaender-volks-schuetzenfest','vierlaender-erdbeerfest','duenenweg-boberg','moorweg-boberg','terrassenweg-boberg','wiesenweg-boberg']);
for(const item of tourismItems){
 if(reviewedInThisSupplement.has(item.id)){
  item.checkedOn='2026-11-22';
  if(item.status==='Quelle am 21.11.2026 geprüft')item.status='Quelle am 22.11.2026 geprüft';
 }
}

for(const highlight of tourismHighlights){
 for(const id of highlight.itemIds){const item=tourismItems.find(entry=>entry.id===id);if(item){item.highlightIds=[...(item.highlightIds||[]),highlight.id];item.highlight=true}}
}

export const tourismById=id=>tourismItems.find(x=>x.id===id)||null;
export const tourismMarkers=tourismItems.filter(x=>Number.isFinite(x.lat)&&Number.isFinite(x.lon)&&x.coordinateSource);
export function filterTourismItems({query='',categoryIds=tourismCategories.map(c=>c.id),freeOnly=false,bikeFriendlyOnly=false}={}){
 const selected=new Set(categoryIds),needle=String(query).trim().toLocaleLowerCase('de');
 return tourismItems.filter(item=>[item.category,...(item.categoryLinks||[])].some(id=>selected.has(id))&&(!freeOnly||Boolean(item.free))&&(!bikeFriendlyOnly||Boolean(item.bikeFriendly))&&(!needle||[item.name,item.description,item.supplementalDescription,item.place,item.address,item.category,item.status,...(item.searchTerms||[]),tourismCategories.find(c=>c.id===item.category)?.label].filter(Boolean).join(' ').toLocaleLowerCase('de').includes(needle)));
}

export function tourismMapKinds(item){
 const ids=[item.category,...(item.categoryLinks||[])],kinds=[];
 if(item.highlightIds?.length)kinds.push('highlights');
 if(ids.includes('sehenswuerdigkeiten'))kinds.push('sights');
 if(ids.includes('rad'))kinds.push('routes');
 if(ids.includes('unterkunft')||ids.includes('camping'))kinds.push('accommodation');
 if(item.specialStay)kinds.push('special-stays');
 if(item.bikeFriendly)kinds.push('bike-stays');
 if(ids.includes('kultur'))kinds.push('culture');
 if(item.eventVenue)kinds.push('events');
 if(ids.includes('familie'))kinds.push('leisure');
 if(ids.includes('wasser'))kinds.push('water');
 if(ids.includes('natur'))kinds.push('nature');
 if(item.geometryType==='area'||item.greenSpace)kinds.push('green');
 if(item.market)kinds.push('markets');
 if(item.mapKinds?.length)kinds.push(...item.mapKinds);
 return [...new Set(kinds)];
}
